<template>
  <dialog ref="dialog" class="node-detail" aria-labelledby="node-detail-title" @cancel.prevent="close" @click="backdrop">
    <header class="detail-heading">
      <div class="node-mark" aria-hidden="true"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="3" y="3" width="18" height="7" rx="2"/><rect x="3" y="14" width="18" height="7" rx="2"/><path d="M7 6.5h.01M7 17.5h.01M12 6.5h5M12 17.5h5" stroke-linecap="round"/></svg></div>
      <div class="node-heading-copy"><div class="heading-line"><h2 id="node-detail-title">{{ node.hostname || '节点详情' }}</h2><span class="node-status" :class="node.status">{{ statusLabel(node.status) }}</span></div><p>{{ node.ip_address }}:{{ node.ssh_port || 22 }} <span>·</span> {{ node.group_name || '未分组' }} <span>·</span> {{ node.collection_mode === 'agent' ? 'Agent 主动上报' : 'SSH 采集' }}</p></div>
      <NodeAlertToggle v-if="node.id" :node="node"/><button class="close-detail" type="button" aria-label="关闭节点详情" @click="close">×</button>
    </header>
    <div class="detail-toolbar"><div class="detail-tabs" role="tablist" aria-label="节点信息"><button :aria-selected="tab === 'metrics'" role="tab" :class="{ active: tab === 'metrics' }" @click="tab = 'metrics'">运行状态</button><button :aria-selected="tab === 'settings'" role="tab" :class="{ active: tab === 'settings' }" @click="tab = 'settings'">节点配置</button></div><span class="updated">{{ ageLabel(node.data_age_seconds) }}</span></div>
    <section v-if="tab === 'metrics'" class="detail-body">
      <div class="detail-metrics" v-if="node.status === 'online'">
        <article v-for="metric in metrics" :key="metric.label" class="summary-metric"><span>{{ metric.label }}</span><strong>{{ metric.value }}<small>{{ metric.unit }}</small></strong><p>{{ metric.note }}</p><div class="metric-track"><i :style="{ width: `${metric.percent}%`, background: metric.color }"/></div></article>
      </div>
      <div v-else class="unavailable"><strong>{{ statusLabel(node.status) }}</strong><p>{{ node.error_message || '等待新的监控数据。可以测试 SSH 连接，或进入运维命令行检查节点。' }}</p></div>
      <div class="process-summary" v-if="node.status === 'online'"><span class="eyebrow">CPU 占用最高的进程</span><p>{{ node.top_process || '暂无进程数据' }}</p><small>进程 CPU 按单核 100% 计算，多线程进程可能超过 100%。</small></div>
      <section class="gpu-section" v-if="node.status === 'online'"><div class="section-caption"><h3>显卡详情</h3><span>{{ node.gpu_data?.length || 0 }} 张 GPU</span></div><div class="gpu-table-wrap" v-if="node.gpu_data?.length"><table><thead><tr><th>设备 / 型号</th><th>显存</th><th>计算占用</th><th>温度</th><th>功率</th></tr></thead><tbody><tr v-for="(gpu, i) in node.gpu_data" :key="gpu.uuid || i"><td><small>GPU {{ i }}</small><strong>{{ gpu.model }}</strong></td><td><span>{{ gpu.memory_used }} / {{ gpu.memory_total }}</span><div class="gpu-memory"><i :style="{ width: `${gpu.memory_percent}%` }"/></div></td><td>{{ gpu.gpu_util_percent == null ? '—' : `${gpu.gpu_util_percent}%` }}</td><td :class="{ hot: parseFloat(gpu.temp) > 80 }">{{ Number.isFinite(parseFloat(gpu.temp)) ? `${parseFloat(gpu.temp)} °C` : '—' }}</td><td>{{ gpu.power_draw == null ? '—' : `${Math.round(gpu.power_draw)} W` }}</td></tr></tbody></table></div><p v-else class="muted">当前没有 NVIDIA 显卡数据。</p></section>
      <footer class="detail-actions"><router-link :to="`/history?server_id=${node.id}`" @click="close">查看历史负载 ↗</router-link><div><button class="secondary-action" @click="goOps('check')">测试 SSH</button><button class="primary-action" @click="goOps('terminal')">进入运维命令行 ↗</button></div></footer>
    </section>
    <form v-else class="detail-body settings-body" @submit.prevent="save">
      <p class="form-description">修改节点连接与采集方式。邮件提醒可通过标题旁的小铃铛单独控制。</p>
      <div class="settings-grid"><label>节点名称<input v-model="form.hostname" required maxlength="100"></label><label>IP 地址<input v-model="form.ip_address" required maxlength="50"></label><label>所属分组<input v-model="form.group_name" list="detail-groups"><datalist id="detail-groups"><option v-for="group in groups" :key="group" :value="group"/></datalist></label><label>采集方式<select v-model="form.collection_mode"><option value="agent">Agent 主动上报 · 每 5 分钟</option><option value="ssh">SSH 用户名密码采集</option></select></label><label>SSH 用户名<input v-model="form.ssh_user" required maxlength="50" autocomplete="off"></label><label>SSH 端口<input v-model.number="form.ssh_port" type="number" min="1" max="65535" step="1" required><small v-if="form.collection_mode === 'agent'">用于安装 Agent 和远程运维，默认 22。</small></label><template v-if="form.collection_mode === 'ssh'"><label class="full-field">SSH 密码<input v-model="form.ssh_password" type="password" autocomplete="new-password" :placeholder="node.has_ssh_password ? '已配置，留空保留原密码' : '输入 SSH 密码'"><small>密码通过 HTTPS 提交并加密保存。修改连接地址、端口或用户名时需重新输入。</small></label></template></div>
      <p v-if="form.collection_mode === 'agent' && node.collection_mode !== 'agent'" class="config-note">切换采集方式不会自动安装 Agent，请先确认节点采集服务已正常运行。</p>
      <AgentHealthPanel v-if="node.collection_mode === 'agent' && form.collection_mode === 'agent'" :server-id="serverId"/>
      <p v-if="error" class="detail-error" role="alert">{{ error }}</p>
      <footer class="detail-actions"><button type="button" class="secondary-action" @click="close">取消</button><button class="primary-action" type="submit" :disabled="saving">{{ saving ? '保存中…' : '保存配置' }}</button></footer>
    </form>
  </dialog>
</template>
<script setup>
import { computed, onBeforeUnmount, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useServers } from '../composables/useServers'
import { api } from '../api'
import { ageLabel, statusLabel } from '../utils/serverStatus'
import NodeAlertToggle from './NodeAlertToggle.vue'
import AgentHealthPanel from './AgentHealthPanel.vue'
const props = defineProps({ serverId: { type: Number, required: true } })
const emit = defineEmits(['close', 'saved'])
const router = useRouter(), { servers } = useServers()
const dialog = ref(null), tab = ref('metrics'), form = ref({}), saving = ref(false), error = ref('')
const node = computed(() => servers.value.find(s => s.id === props.serverId) || { status: 'pending' })
const groups = computed(() => [...new Set(servers.value.map(s => s.group_name).filter(Boolean))])
const metrics = computed(() => {
  const s = node.value, gpus = s.gpu_data || [], power = gpus.reduce((n,g) => n+(g.power_draw || 0),0)
  const gpuAverage = gpus.length ? gpus.reduce((n,g) => n+(g.memory_percent || 0),0)/gpus.length : 0
  return [
    {label:'CPU 使用率',value:Math.round(s.cpu_percent || 0),unit:'%',note:`${s.cpu_cores || 0} 个逻辑核心`,percent:s.cpu_percent || 0,color:'#2563eb'},
    {label:'内存使用率',value:Math.round(s.ram_percent || 0),unit:'%',note:`${((s.ram_used_mb || 0)/1024).toFixed(1)} / ${((s.ram_total_mb || 0)/1024).toFixed(1)} GB`,percent:s.ram_percent || 0,color:'#0d9488'},
    {label:'平均显存占用',value:Math.round(gpuAverage),unit:'%',note:`${gpus.length} 张 NVIDIA 显卡`,percent:gpuAverage,color:'#7c3aed'},
    {label:'GPU 总功率',value:Math.round(power),unit:'W',note:'所有显卡当前功率之和',percent:0,color:'#f59e0b'},
  ]
})
function close() { form.value.ssh_password = ''; emit('close') }
function backdrop(event) { if (event.target === dialog.value) { const r = dialog.value.getBoundingClientRect(); if (event.clientX < r.left || event.clientX > r.right || event.clientY < r.top || event.clientY > r.bottom) close() } }
function goOps(action) { router.push({ path:`/nodes/${props.serverId}/operations`,query:action ? {action} : {} }); close() }
async function save() {
  error.value = ''
  if (form.value.ssh_password && location.protocol !== 'https:') { error.value = '请使用 HTTPS 页面提交密码。'; return }
  saving.value = true
  try { const { ssh_password,...data }=form.value; if (data.collection_mode === 'ssh' && ssh_password) data.ssh_password=ssh_password; await api.updateServer(props.serverId,data); form.value.ssh_password=''; emit('saved'); close() }
  catch(e) { error.value = e.response?.data?.detail || '保存失败，请检查输入后重试。' }
  finally { saving.value=false }
}
onMounted(() => { const s=node.value; form.value={hostname:s.hostname,ip_address:s.ip_address,group_name:s.group_name,collection_mode:s.collection_mode,ssh_user:s.ssh_user || 'root',ssh_port:s.ssh_port || 22,ssh_password:''}; dialog.value.showModal() })
onBeforeUnmount(() => { form.value.ssh_password=''; dialog.value?.close() })
</script>
<style scoped>
.node-detail{width:980px;max-width:calc(100vw - 40px);max-height:90dvh;padding:0;border:1px solid var(--border);border-radius:20px;background:var(--surface);color:var(--text);box-shadow:var(--shadow-modal);overflow:auto;box-sizing:border-box}.node-detail::backdrop{background:var(--backdrop);backdrop-filter:blur(4px)}.node-detail *{box-sizing:border-box}.detail-heading{display:flex;gap:16px;align-items:center;padding:26px 30px;background:linear-gradient(115deg,var(--accent-soft),var(--surface) 70%);border-bottom:1px solid var(--border-soft)}.node-mark{display:grid;place-items:center;flex-shrink:0;width:48px;height:48px;border:1px solid var(--accent-border);border-radius:14px;background:var(--surface);color:var(--accent)}.node-mark svg{width:28px;height:28px}.node-heading-copy{min-width:0;flex:1}.heading-line{display:flex;gap:14px;align-items:center;flex-wrap:wrap}.heading-line h2{font-size:21px;margin:0;overflow-wrap:anywhere}.detail-heading p{margin:7px 0 0;font-size:12px;color:var(--text-muted)}.detail-heading p span{margin:0 6px;color:var(--border)}.node-status{font-size:11px;border-radius:20px;background:var(--surface-muted);padding:4px 10px}.node-status.online{background:var(--success-bg)}.node-status.offline{background:var(--danger-bg)}.close-detail{border:0;background:transparent;color:var(--text-muted);font-size:27px;cursor:pointer;padding:2px 5px}.detail-toolbar{display:flex;justify-content:space-between;align-items:center;padding:0 30px;border-bottom:1px solid var(--border-soft)}.detail-tabs{display:flex;gap:26px}.detail-tabs button{padding:17px 0;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--text-muted);font-weight:600;cursor:pointer}.detail-tabs button.active{color:var(--accent);border-bottom-color:var(--accent)}.updated{font-size:12px;color:var(--text-muted)}.detail-body{padding:26px 30px}.detail-metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px}.summary-metric{padding:17px;border:1px solid var(--border-soft);border-radius:13px;background:var(--surface)}.summary-metric>span{font-size:12px;color:var(--text-muted)}.summary-metric strong{display:block;font-size:29px;letter-spacing:-1px;margin-top:12px}.summary-metric strong small{font-size:13px;color:var(--text-muted);margin-left:4px;letter-spacing:0}.summary-metric p{font-size:11px;color:var(--text-muted);margin:7px 0 13px}.metric-track,.gpu-memory{height:4px;background:var(--surface-muted);border-radius:4px;overflow:hidden}.metric-track i,.gpu-memory i{display:block;height:100%;border-radius:4px}.process-summary{margin-top:20px;padding:17px 20px;border:1px solid var(--border-soft);border-radius:13px;background:var(--surface-soft)}.eyebrow{font-size:11px;font-weight:600;color:var(--text-muted)}.process-summary p{font:13px/1.8 ui-monospace,monospace;overflow-wrap:anywhere;margin:8px 0}.process-summary small{font-size:11px;color:var(--text-muted)}.gpu-section{margin-top:26px}.section-caption{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.section-caption h3{font-size:14px;margin:0}.section-caption span{font-size:11px;background:var(--accent-soft);padding:4px 8px;color:var(--accent);border-radius:5px}.gpu-table-wrap{overflow:auto;border:1px solid var(--border-soft);border-radius:12px}table{width:100%;border-collapse:collapse;text-align:left;font-size:12px;white-space:nowrap}th{background:var(--surface-soft);color:var(--text-muted);font-size:11px;font-weight:500;padding:12px 16px}td{padding:14px 16px;border-top:1px solid var(--surface-muted);color:var(--text-secondary)}td strong{display:block;font-size:12px;font-weight:500;color:var(--text);margin-top:4px}td small{color:var(--text-muted);font-size:10px}.gpu-memory{margin-top:8px;max-width:180px}.gpu-memory i{background:var(--metric-gpu)}.hot{color:var(--danger)}.muted,.form-description{font-size:13px;line-height:1.7;color:var(--text-muted)}.unavailable{padding:30px;border:1px dashed var(--border);border-radius:13px;background:var(--surface-soft);text-align:center}.unavailable p{font-size:13px;color:var(--text-muted);line-height:1.7}.detail-actions{display:flex;justify-content:space-between;align-items:center;gap:12px;border-top:1px solid var(--border-soft);margin-top:24px;padding-top:20px}.detail-actions>div{display:flex;gap:10px}.detail-actions a{font-size:12px;text-decoration:none;color:var(--text-muted)}.primary-action,.secondary-action{padding:10px 16px;border-radius:8px;font-size:12px;font-weight:600;cursor:pointer;border:1px solid var(--border);background:var(--surface);color:var(--text-secondary)}.primary-action{color:var(--on-primary);background:var(--primary-bg);border-color:var(--primary-bg)}.primary-action:hover{background:var(--primary-hover)}.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:22px 0}.settings-grid label{display:flex;flex-direction:column;gap:8px;font-size:12px;color:var(--text-secondary)}.settings-grid input,.settings-grid select{width:100%;height:42px;padding:10px 12px;border:1px solid var(--border);border-radius:8px;background:var(--surface);color:var(--text);outline:none;font:inherit}.settings-grid input:focus,.settings-grid select:focus{border-color:var(--accent-border);box-shadow:0 0 0 3px var(--accent-soft)}.full-field{grid-column:1/-1}.settings-grid small{font-size:11px;color:var(--text-muted)}.config-note{background:var(--accent-soft);padding:13px;border-radius:8px;color:var(--text-secondary);font-size:12px;line-height:1.7}.detail-error{color:var(--danger);font-size:12px}button:focus-visible,a:focus-visible{outline:3px solid var(--focus);outline-offset:3px}@media(max-width:700px){.detail-heading,.detail-body{padding:20px}.detail-toolbar{padding:0 20px}.node-mark{display:none}.detail-metrics{grid-template-columns:1fr 1fr}.settings-grid{grid-template-columns:1fr}.detail-actions{flex-wrap:wrap}.updated{font-size:10px}.detail-tabs{gap:18px}.heading-line h2{font-size:18px}}
</style>
